USE [JamunaBankProcurement];
GO
CREATE OR ALTER PROCEDURE dbo.usp_ConcernDivisionSetup_GetAll @ActiveOnly BIT=1
AS BEGIN SET NOCOUNT ON; SELECT s.CONCERN_DIVISION_ID,s.ORG_UNIT_ID,s.SETUP_CODE,s.IS_ACTIVE,o.ORG_UNIT_CODE,o.ORG_UNIT_NAME,o.ORG_UNIT_TYPE FROM dbo.CONCERN_DIVISION_SETUP s JOIN dbo.ORG_UNIT o ON o.ORG_UNIT_ID=s.ORG_UNIT_ID WHERE @ActiveOnly=0 OR s.IS_ACTIVE=1 ORDER BY o.ORG_UNIT_NAME; END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_ConcernDivisionOfficial_GetByDivision @ConcernDivisionId BIGINT,@ActiveOnly BIT=1
AS BEGIN SET NOCOUNT ON; SELECT CONVERT(BIGINT,m.CONCERN_OFFICIAL_ID) CONCERN_OFFICIAL_ID,CONVERT(BIGINT,m.CONCERN_DIVISION_ID) CONCERN_DIVISION_ID,m.EMPLOYEE_ID,CONVERT(BIT,m.IS_ACTIVE) IS_ACTIVE,CONVERT(DATETIME2,m.EFFECTIVE_FROM) EFFECTIVE_FROM,CONVERT(DATETIME2,m.EFFECTIVE_TO) EFFECTIVE_TO,u.DISPLAY_NAME,u.EMAIL,u.DESIGNATION FROM dbo.CONCERN_DIVISION_OFFICIAL m LEFT JOIN dbo.APP_USER_CACHE u ON u.EMPLOYEE_ID=m.EMPLOYEE_ID WHERE m.CONCERN_DIVISION_ID=@ConcernDivisionId AND (@ActiveOnly=0 OR m.IS_ACTIVE=1) ORDER BY u.DISPLAY_NAME,m.EMPLOYEE_ID; END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_ConcernDivisionAuthority_GetByDivision @ConcernDivisionId BIGINT,@ActiveOnly BIT=1
AS BEGIN SET NOCOUNT ON; SELECT CONVERT(BIGINT,m.CONCERN_AUTHORITY_ID) CONCERN_AUTHORITY_ID,CONVERT(BIGINT,m.CONCERN_DIVISION_ID) CONCERN_DIVISION_ID,m.EMPLOYEE_ID,CONVERT(INT,m.AUTHORITY_LEVEL) AUTHORITY_LEVEL,CONVERT(BIT,m.IS_ACTIVE) IS_ACTIVE,CONVERT(DATETIME2,m.EFFECTIVE_FROM) EFFECTIVE_FROM,CONVERT(DATETIME2,m.EFFECTIVE_TO) EFFECTIVE_TO,u.DISPLAY_NAME,u.EMAIL,u.DESIGNATION FROM dbo.CONCERN_DIVISION_AUTHORITY m LEFT JOIN dbo.APP_USER_CACHE u ON u.EMPLOYEE_ID=m.EMPLOYEE_ID WHERE m.CONCERN_DIVISION_ID=@ConcernDivisionId AND (@ActiveOnly=0 OR m.IS_ACTIVE=1) ORDER BY m.AUTHORITY_LEVEL,u.DISPLAY_NAME,m.EMPLOYEE_ID; END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_ConcernDivisionOfficial_Add @ConcernDivisionId BIGINT,@EmployeeId VARCHAR(30),@EffectiveFrom DATE,@EffectiveTo DATE=NULL,@Actor VARCHAR(50)
AS BEGIN SET NOCOUNT ON; BEGIN TRY IF EXISTS(SELECT 1 FROM dbo.CONCERN_DIVISION_OFFICIAL WHERE CONCERN_DIVISION_ID=@ConcernDivisionId AND EMPLOYEE_ID=@EmployeeId AND IS_ACTIVE=1) THROW 51005,'Employee is already an active official for this division.',1; INSERT dbo.CONCERN_DIVISION_OFFICIAL(CONCERN_DIVISION_ID,EMPLOYEE_ID,EFFECTIVE_FROM,EFFECTIVE_TO,CREATED_BY) VALUES(@ConcernDivisionId,@EmployeeId,@EffectiveFrom,@EffectiveTo,@Actor); SELECT '000' RESULT_CODE,N'Success' RESULT_MESSAGE,CONVERT(BIGINT,SCOPE_IDENTITY()) ENTITY_ID,NULL REFERENCE_NO; END TRY BEGIN CATCH SELECT CASE WHEN ERROR_NUMBER() IN(2601,2627,51005) THEN '005' WHEN ERROR_NUMBER()=547 THEN '001' ELSE '999' END RESULT_CODE,ERROR_MESSAGE() RESULT_MESSAGE,NULL ENTITY_ID,NULL REFERENCE_NO; END CATCH END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_ConcernDivisionOfficial_Deactivate @ConcernOfficialId BIGINT,@Actor VARCHAR(50)
AS BEGIN SET NOCOUNT ON; UPDATE dbo.CONCERN_DIVISION_OFFICIAL SET IS_ACTIVE=0,EFFECTIVE_TO=COALESCE(EFFECTIVE_TO,CONVERT(DATE,SYSUTCDATETIME())),MODIFIED_BY=@Actor,MODIFIED_DATE=SYSUTCDATETIME() WHERE CONCERN_OFFICIAL_ID=@ConcernOfficialId AND IS_ACTIVE=1; SELECT CASE WHEN @@ROWCOUNT=1 THEN '000' ELSE '002' END RESULT_CODE,CASE WHEN @@ROWCOUNT=1 THEN N'Success' ELSE N'Active mapping not found' END RESULT_MESSAGE,@ConcernOfficialId ENTITY_ID,NULL REFERENCE_NO; END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_ConcernDivisionAuthority_Add @ConcernDivisionId BIGINT,@EmployeeId VARCHAR(30),@AuthorityLevel INT,@EffectiveFrom DATE,@EffectiveTo DATE=NULL,@Actor VARCHAR(50)
AS BEGIN SET NOCOUNT ON; BEGIN TRY IF EXISTS(SELECT 1 FROM dbo.CONCERN_DIVISION_AUTHORITY WHERE CONCERN_DIVISION_ID=@ConcernDivisionId AND EMPLOYEE_ID=@EmployeeId AND IS_ACTIVE=1) THROW 51005,'Employee is already an active authority for this division.',1; INSERT dbo.CONCERN_DIVISION_AUTHORITY(CONCERN_DIVISION_ID,EMPLOYEE_ID,AUTHORITY_LEVEL,EFFECTIVE_FROM,EFFECTIVE_TO,CREATED_BY) VALUES(@ConcernDivisionId,@EmployeeId,@AuthorityLevel,@EffectiveFrom,@EffectiveTo,@Actor); SELECT '000' RESULT_CODE,N'Success' RESULT_MESSAGE,CONVERT(BIGINT,SCOPE_IDENTITY()) ENTITY_ID,NULL REFERENCE_NO; END TRY BEGIN CATCH SELECT CASE WHEN ERROR_NUMBER() IN(2601,2627,51005) THEN '005' WHEN ERROR_NUMBER()=547 THEN '001' ELSE '999' END RESULT_CODE,ERROR_MESSAGE() RESULT_MESSAGE,NULL ENTITY_ID,NULL REFERENCE_NO; END CATCH END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_ConcernDivisionAuthority_Deactivate @ConcernAuthorityId BIGINT,@Actor VARCHAR(50)
AS BEGIN SET NOCOUNT ON; UPDATE dbo.CONCERN_DIVISION_AUTHORITY SET IS_ACTIVE=0,EFFECTIVE_TO=COALESCE(EFFECTIVE_TO,CONVERT(DATE,SYSUTCDATETIME())),MODIFIED_BY=@Actor,MODIFIED_DATE=SYSUTCDATETIME() WHERE CONCERN_AUTHORITY_ID=@ConcernAuthorityId AND IS_ACTIVE=1; SELECT CASE WHEN @@ROWCOUNT=1 THEN '000' ELSE '002' END RESULT_CODE,CASE WHEN @@ROWCOUNT=1 THEN N'Success' ELSE N'Active mapping not found' END RESULT_MESSAGE,@ConcernAuthorityId ENTITY_ID,NULL REFERENCE_NO; END;
GO
